-- ============================================================================
-- Mầm Xanh LMS 2.0 — Supabase (PostgreSQL) Cloud Schema & Authentic Seed Data
-- Generated directly from Moodle 4.5 LTS database (mamxanh_lms_db_backup.sql)
-- Includes 42 HMAC-SHA256 Digital Certificates, 27 VietGAP Batches, 54 Diary Logs
-- ============================================================================

-- 1. Digital Training Certificates (HMAC-SHA256)
CREATE TABLE IF NOT EXISTS public.mamxanh_certificates (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  cert_code VARCHAR(64) NOT NULL UNIQUE,
  student_name VARCHAR(255) NOT NULL,
  student_username VARCHAR(100) NOT NULL,
  farm_name VARCHAR(255) NOT NULL DEFAULT '',
  course_code VARCHAR(64) NOT NULL,
  course_name VARCHAR(255) NOT NULL,
  final_score NUMERIC(6,2) NOT NULL DEFAULT 0.00,
  hmac_signature VARCHAR(128) NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'valid',
  issued_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  moodle_userid INTEGER NOT NULL DEFAULT 0,
  moodle_courseid INTEGER NOT NULL DEFAULT 0,
  issued_unix BIGINT NOT NULL DEFAULT EXTRACT(EPOCH FROM NOW())::BIGINT
);

-- 2. VietGAP Agricultural Production Batches
CREATE TABLE IF NOT EXISTS public.agriops_batches (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  batch_code VARCHAR(64) NOT NULL UNIQUE,
  product_name VARCHAR(255) NOT NULL,
  crop_variety VARCHAR(120) NOT NULL,
  farmer_name VARCHAR(255) NOT NULL DEFAULT '',
  farm_name VARCHAR(255) NOT NULL DEFAULT '',
  region VARCHAR(100) NOT NULL DEFAULT 'Lâm Đồng',
  gps_coords VARCHAR(64) NOT NULL DEFAULT '11.940419, 108.458313',
  area_m2 INTEGER NOT NULL DEFAULT 1000,
  expected_yield_kg INTEGER NOT NULL DEFAULT 500,
  vietgap_status VARCHAR(40) NOT NULL DEFAULT 'active',
  qr_token VARCHAR(64) NOT NULL DEFAULT '',
  hmac_signature VARCHAR(128) NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 3. Electronic Cultivation Field Diary Logs
CREATE TABLE IF NOT EXISTS public.agriops_logs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  batch_code VARCHAR(64) NOT NULL REFERENCES public.agriops_batches(batch_code) ON DELETE CASCADE,
  activity_type VARCHAR(60) NOT NULL DEFAULT 'watering_fert',
  notes TEXT NOT NULL,
  ph_val VARCHAR(20) NOT NULL DEFAULT '6.0',
  ec_val VARCHAR(20) NOT NULL DEFAULT '1.6',
  phi_days INTEGER NOT NULL DEFAULT 0,
  logged_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 4. Automated Fertigation Calculator Recipes
CREATE TABLE IF NOT EXISTS public.fertigation_records (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  crop_stage VARCHAR(255) NOT NULL,
  tank_volume_l NUMERIC(10,2) NOT NULL,
  target_ec NUMERIC(6,2) NOT NULL,
  target_ph VARCHAR(40) NOT NULL,
  stock_a_ml NUMERIC(10,2) NOT NULL,
  stock_b_ml NUMERIC(10,2) NOT NULL,
  acid_ml NUMERIC(10,2) NOT NULL,
  recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_mamxanh_cert_code ON public.mamxanh_certificates(cert_code);
CREATE INDEX IF NOT EXISTS idx_agriops_batch_code ON public.agriops_batches(batch_code);
CREATE INDEX IF NOT EXISTS idx_agriops_logs_batch ON public.agriops_logs(batch_code, logged_at DESC);

-- ============================================================================
-- Row Level Security (RLS): Public Read + Serverless API Service-Role Write
-- ============================================================================
ALTER TABLE public.mamxanh_certificates ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.agriops_batches ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.agriops_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.fertigation_records ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public read certificates" ON public.mamxanh_certificates;
CREATE POLICY "Public read certificates" ON public.mamxanh_certificates FOR SELECT USING (true);
DROP POLICY IF EXISTS "API write certificates" ON public.mamxanh_certificates;
CREATE POLICY "API write certificates" ON public.mamxanh_certificates FOR ALL TO service_role USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public read batches" ON public.agriops_batches;
CREATE POLICY "Public read batches" ON public.agriops_batches FOR SELECT USING (true);
DROP POLICY IF EXISTS "API write batches" ON public.agriops_batches;
CREATE POLICY "API write batches" ON public.agriops_batches FOR ALL TO service_role USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public read logs" ON public.agriops_logs;
CREATE POLICY "Public read logs" ON public.agriops_logs FOR SELECT USING (true);
DROP POLICY IF EXISTS "API write logs" ON public.agriops_logs;
CREATE POLICY "API write logs" ON public.agriops_logs FOR ALL TO service_role USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public read fertigation" ON public.fertigation_records;
CREATE POLICY "Public read fertigation" ON public.fertigation_records FOR SELECT USING (true);
DROP POLICY IF EXISTS "API write fertigation" ON public.fertigation_records;
CREATE POLICY "API write fertigation" ON public.fertigation_records FOR ALL TO service_role USING (true) WITH CHECK (true);

