-- ============================================================================
-- FULL-STACK LMS EXTENSION TABLES (6 Core Tables + Seed Data + RLS)
-- ============================================================================

-- 5. LMS Users (PBKDF2 SHA-512 Authentication + 3-Role RBAC)
CREATE TABLE IF NOT EXISTS public.lms_users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username VARCHAR(80) NOT NULL UNIQUE,
  email VARCHAR(160) NOT NULL UNIQUE,
  password_hash VARCHAR(256) NOT NULL,
  salt VARCHAR(64) NOT NULL,
  full_name VARCHAR(160) NOT NULL,
  role VARCHAR(20) NOT NULL DEFAULT 'student' CHECK (role IN ('student', 'teacher', 'admin')),
  farm_name VARCHAR(255) NOT NULL DEFAULT '',
  region VARCHAR(100) NOT NULL DEFAULT 'Lâm Đồng',
  area_m2 INTEGER NOT NULL DEFAULT 1000,
  main_crop VARCHAR(160) NOT NULL DEFAULT 'Rau & Dâu tây Công nghệ cao',
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 6. LMS Standardized Agricultural Courses (8 Core Courses + Clones)
CREATE TABLE IF NOT EXISTS public.lms_courses (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code VARCHAR(64) NOT NULL UNIQUE,
  fullname VARCHAR(255) NOT NULL,
  category VARCHAR(120) NOT NULL DEFAULT 'Kỹ thuật Canh tác CNC',
  summary TEXT NOT NULL DEFAULT '',
  modules_count INTEGER NOT NULL DEFAULT 14,
  is_cloned BOOLEAN NOT NULL DEFAULT false,
  created_by VARCHAR(80) NOT NULL DEFAULT 'admin',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 7. LMS Course Enrollments & Gradebook Sync
CREATE TABLE IF NOT EXISTS public.lms_enrollments (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES public.lms_users(id) ON DELETE CASCADE,
  course_code VARCHAR(64) NOT NULL REFERENCES public.lms_courses(code) ON DELETE CASCADE,
  progress_pct NUMERIC(5,2) NOT NULL DEFAULT 0.00,
  quiz_score NUMERIC(5,2) NOT NULL DEFAULT 0.00,
  attendance_count INTEGER NOT NULL DEFAULT 0,
  status VARCHAR(32) NOT NULL DEFAULT 'enrolled',
  enrolled_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, course_code)
);

-- 8. LMS Field Practice Check-ins (QR + GPS) & 4-Criteria Rubric Grading
CREATE TABLE IF NOT EXISTS public.lms_fieldpractice_subs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES public.lms_users(id) ON DELETE CASCADE,
  course_code VARCHAR(64) NOT NULL REFERENCES public.lms_courses(code) ON DELETE CASCADE,
  checkin_code VARCHAR(64) NOT NULL,
  gps_lat VARCHAR(32) NOT NULL,
  gps_lng VARCHAR(32) NOT NULL,
  distance_m INTEGER NOT NULL DEFAULT 0,
  crit_prep INTEGER NOT NULL DEFAULT 0 CHECK (crit_prep BETWEEN 0 AND 25),
  crit_tech INTEGER NOT NULL DEFAULT 0 CHECK (crit_tech BETWEEN 0 AND 25),
  crit_biosafe INTEGER NOT NULL DEFAULT 0 CHECK (crit_biosafe BETWEEN 0 AND 25),
  crit_quality INTEGER NOT NULL DEFAULT 0 CHECK (crit_quality BETWEEN 0 AND 25),
  total_grade NUMERIC(5,2) NOT NULL DEFAULT 0.00,
  feedback TEXT NOT NULL DEFAULT '',
  graded_by VARCHAR(80) DEFAULT NULL,
  submitted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  graded_at TIMESTAMPTZ DEFAULT NULL
);

-- 9. LMS Quiz Attempts Ledger
CREATE TABLE IF NOT EXISTS public.lms_quiz_attempts (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES public.lms_users(id) ON DELETE CASCADE,
  course_code VARCHAR(64) NOT NULL REFERENCES public.lms_courses(code) ON DELETE CASCADE,
  score_100 NUMERIC(5,2) NOT NULL DEFAULT 0.00,
  answers_json JSONB NOT NULL DEFAULT '{}'::jsonb,
  attempted_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 10. LMS Agricultural Extension News & Notices
CREATE TABLE IF NOT EXISTS public.lms_news (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  category VARCHAR(100) NOT NULL,
  title VARCHAR(255) NOT NULL UNIQUE,
  summary TEXT NOT NULL,
  content TEXT NOT NULL,
  published_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_lms_users_username ON public.lms_users(username);
CREATE INDEX IF NOT EXISTS idx_lms_enrollments_user ON public.lms_enrollments(user_id);
CREATE INDEX IF NOT EXISTS idx_lms_fp_user_course ON public.lms_fieldpractice_subs(user_id, course_code);
CREATE INDEX IF NOT EXISTS idx_lms_quiz_user_course ON public.lms_quiz_attempts(user_id, course_code);

-- ============================================================================
-- RLS Policies for 6 New LMS Tables (Private PII protected, API Service-Role)
-- ============================================================================
ALTER TABLE public.lms_users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lms_courses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lms_enrollments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lms_fieldpractice_subs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lms_quiz_attempts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lms_news ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "API full lms_users" ON public.lms_users;
CREATE POLICY "API full lms_users" ON public.lms_users FOR ALL TO service_role USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public read lms_courses" ON public.lms_courses;
CREATE POLICY "Public read lms_courses" ON public.lms_courses FOR SELECT USING (true);
DROP POLICY IF EXISTS "API write lms_courses" ON public.lms_courses;
CREATE POLICY "API write lms_courses" ON public.lms_courses FOR ALL TO service_role USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "API full lms_enrollments" ON public.lms_enrollments;
CREATE POLICY "API full lms_enrollments" ON public.lms_enrollments FOR ALL TO service_role USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "API full lms_fieldpractice_subs" ON public.lms_fieldpractice_subs;
CREATE POLICY "API full lms_fieldpractice_subs" ON public.lms_fieldpractice_subs FOR ALL TO service_role USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "API full lms_quiz_attempts" ON public.lms_quiz_attempts;
CREATE POLICY "API full lms_quiz_attempts" ON public.lms_quiz_attempts FOR ALL TO service_role USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public read lms_news" ON public.lms_news;
CREATE POLICY "Public read lms_news" ON public.lms_news FOR SELECT USING (true);
DROP POLICY IF EXISTS "API write lms_news" ON public.lms_news;
CREATE POLICY "API write lms_news" ON public.lms_news FOR ALL TO service_role USING (true) WITH CHECK (true);

