INSERT INTO public.lms_courses (id, code, fullname, category, summary, modules_count, is_cloned, created_by)
VALUES
  (1, 'CHAMSOC01', 'Kỹ thuật Canh tác Nông nghiệp Công nghệ cao & Dinh dưỡng Tự động', 'Kỹ thuật Nhà màng & Dinh dưỡng', 'Học phần trang bị kiến thức chuyên sâu về vi khí hậu nhà màng, hệ thống tưới nhỏ giọt bù áp, quản lý dinh dưỡng khoáng pH/EC tự động và phác đồ kiểm soát dịch hại sinh học (IPM) theo chuẩn VietGAP TCVN 11892-1:2017.', 23, false, 'admin'),
  (2, 'CHEBIEN01', 'Công nghệ Sơ chế, Chế biến Sâu & Bảo quản Lạnh Nông sản Xuất khẩu', 'Sau thu hoạch & Bảo quản', 'Làm chủ chuỗi giá trị sau thu hoạch: Hạ nhiệt đồng ruộng (Pre-cooling) trong 2 giờ vàng, công nghệ sấy lạnh bơm nhiệt, đóng gói khí quyển biến đổi MAP/CA, kho lạnh thông minh và cấp mã QR VietGAP.', 15, false, 'admin'),
  (3, 'IOTNHAMANG01', 'Vận hành Nhà màng Thông minh & Trạm Cảm biến Vi khí hậu IoT', 'Nông nghiệp Thông minh & IoT', 'Làm chủ hệ thống cảm biến nhiệt-ẩm-ánh sáng PAR-CO2, chỉ số thiếu hụt áp suất hơi nước VPD, điều khiển tự động lưới cắt nắng, quạt đối lưu và màn mưa Cooling Pad.', 14, false, 'admin'),
  (4, 'THUYCANH01', 'Kỹ thuật Thủy canh Hồi lưu NFT & Giá thể Xơ dừa Chuẩn VietGAP', 'Thủy canh & Giá thể', 'Thiết kế độ dốc máng thủy canh màng dinh dưỡng NFT 1:40, kiểm soát oxy hòa tan DO >= 6 mg/L, xử lý xơ dừa xả chát Tanin/EC và kiểm soát dư lượng nitrat trước thu hoạch.', 14, false, 'admin'),
  (5, 'SAURIENG01', 'Quy trình Canh tác Sầu riêng Xuất khẩu, Mã số Vùng trồng & Xử lý Ra hoa', 'Cây ăn trái Xuất khẩu', 'Chuẩn hóa quy trình canh tác Sầu riêng Dona/Ri6 phục vụ xuất khẩu chính ngạch: Quản lý cơi đọt, xiết nước ra hoa đồng loạt, phòng chống Phytophthora & Rệp sáp, quản lý Mã số vùng trồng (PUC).', 14, false, 'admin'),
  (6, 'PHANVISINH01', 'Sản xuất Phân Hữu cơ Vi sinh, Nhân sinh khối Trichoderma & Cải tạo Đất', 'Vi sinh & Tuần hoàn Đất', 'Tận dụng phụ phẩm nông nghiệp ủ hiếu khí 55-65 độ C theo tỷ lệ C/N = 25-30:1, nhân sinh khối nấm đối kháng Trichoderma spp. và Bacillus subtilis cải tạo hệ vi sinh đất.', 14, false, 'admin'),
  (7, 'DAUTAY-CNC-01', 'Kỹ thuật Canh tác Dâu tây & Hoa Cúc Công nghệ cao trong Nhà màng Đà Lạt', 'Cây trồng Chủ lực Đà Lạt', 'Quy trình chuẩn hóa canh tác Dâu tây Albion và Hoa cúc cắt cành trên giá thể treo tại Đà Lạt: kiểm soát vi khí hậu, châm phân nhỏ giọt, IPM sinh học và truy xuất nguồn gốc VietGAP.', 14, false, 'admin'),
  (8, 'DAUTAY-DONDUONG-01', 'Tập huấn Kỹ thuật Dâu tây & Hoa Cúc CNC - HTX Đơn Dương', 'Chuyển giao Hợp tác xã', 'Phiên bản khóa học nhân bản dành riêng cho hội viên Hợp tác xã Đơn Dương (Lâm Đồng) với trạm thực hành GPS thực địa ngay tại vùng nguyên liệu Đơn Dương.', 14, true, 'cbkt_pilot')
ON CONFLICT (code) DO NOTHING;

SELECT setval(pg_get_serial_sequence('public.lms_courses', 'id'), COALESCE((SELECT MAX(id) FROM public.lms_courses), 1), true);

