-- Seed Data: 4 Extension Press Articles (lms_news)
-- ============================================================================
INSERT INTO public.lms_news (id, category, title, summary, content)
VALUES
  (1, 'Kỹ thuật Canh tác', 'Ứng dụng tưới nhỏ giọt bù áp & châm phân tự động (Fertigation) tiết kiệm 40% phân bón', 'Kiểm soát EC 1.2–2.2 mS/cm và pH 5.6–6.2 theo từng giai đoạn sinh trưởng trong nhà màng Lâm Đồng.', '<p><strong>1. Đặt vấn đề:</strong> Tưới tràn truyền thống gây thất thoát đạm nitrat và tích tụ muối cục bộ trên giá thể xơ dừa. Hệ thống tưới nhỏ giọt bù áp (1.6–2.0 L/h) kết hợp bộ châm phân tự động giúp đồng đều dinh dưỡng tới 95%.</p><p><strong>2. Kết quả thực tiễn:</strong> Giảm 40% lượng phân bón hòa tan, tiết kiệm 32% nước tưới và tăng 24% tỷ lệ nông sản loại A đạt chuẩn xuất khẩu.</p>'),
  (2, 'Bảo vệ Thực vật', 'Phác đồ Quản lý dịch hại tổng hợp (IPM) & chế phẩm sinh học Trichoderma phòng bệnh héo rũ', 'Nhận diện sớm nấm Fusarium, Phytophthora và kết hợp bẫy dính sinh học đảm bảo thời gian cách ly PHI = 0 ngày.', '<p><strong>1. Giám sát dịch tễ:</strong> Điều tra 5 điểm chéo góc định kỳ 7 ngày/lần khi ẩm độ nhà màng vượt 85%.</p><p><strong>2. Biện pháp sinh học:</strong> Ủ hoạt hóa nấm đối kháng <em>Trichoderma spp.</em> cùng vi khuẩn <em>Bacillus subtilis</em> vào giá thể, kết hợp 40 bẫy dính vàng/xanh trên 1.000 m2 giúp triệt tiêu dư lượng thuốc BVTV hóa học.</p>'),
  (3, 'Tiêu chuẩn & Xuất khẩu', 'Quy trình ghi chép nhật ký đồng ruộng điện tử & cấp mã số vùng trồng truy xuất QR', 'Số hóa biểu mẫu theo TCVN 11892-1:2017 và ký xác thực lô nông sản bằng thuật toán mật mã HMAC-SHA256.', '<p><strong>1. Nhật ký điện tử 24h:</strong> Toàn bộ tác nghiệp pha tưới, phòng trừ sinh học và thu hoạch được ghi trực tiếp qua Web hoặc Nhật ký Cloud.</p><p><strong>2. Hộ chiếu nông sản QR:</strong> Mỗi lô nông sản thu hoạch được gắn mã truy xuất công khai cho phép đơn vị thu mua kiểm tra lịch sử canh tác tức thì.</p>'),
  (4, 'Thông báo Đào tạo', 'Kế hoạch mở lớp tập huấn Dâu tây & Hoa Cúc Công nghệ cao đợt tháng 11/2026', 'Học phần DAUTAY-CNC-01 gồm 04 chuyên đề trực tuyến, H5P, SCORM 1.2 và thực hành QR+GPS tại Đà Lạt.', '<p><strong>1. Cấu trúc chương trình:</strong> 04 chuyên đề từ xử lý giá thể, điều tiết vi khí hậu, tưới nhỏ giọt Fertigation đến phòng trừ IPM.</p><p><strong>2. Điều kiện cấp chứng nhận:</strong> Quiz cuối khóa >= 70% và hoàn thành chấm Rubric 4 tiêu chí tại vườn >= 60 điểm.</p>')
ON CONFLICT (title) DO NOTHING;

SELECT setval(pg_get_serial_sequence('public.lms_news', 'id'), COALESCE((SELECT MAX(id) FROM public.lms_news), 1), true);
